import { writeFile } from 'node:fs/promises';
import { loadMcpConfig } from '/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/dist/extensions/mcp/config.js';
import { McpServerConnection, McpOAuthCredentialStore, createDefaultTransport } from '/opt/homebrew/lib/node_modules/@earendil-works/pi-coding-agent/dist/extensions/mcp/runtime.js';

// Use Pi's credential store and refresh lock without copying or printing tokens.
// Discovery does not invoke mailbox tools or expose write tools to the model.
const credentials = new McpOAuthCredentialStore();
const entry = loadMcpConfig({agentDir:'/Users/heath/.pi/agent',cwd:'/Users/heath/code/mrmr',projectTrusted:false}).servers.find(s => s.name === 'superhuman-mail');
if (!entry || entry.config.url !== 'https://mcp.mail.superhuman.com/mcp') throw new Error('Unexpected MCP configuration');
const connection = new McpServerConnection({entry,cwd:'/Users/heath/code/mrmr',credentials,createTransport:createDefaultTransport,onTools:()=>{}});
try {
  await connection.getClient();
  const names = ['list_accounts','list_threads','get_thread','get_message'];
  const tools = connection.tools.filter(t => names.includes(t.name));
  if (tools.length !== names.length) throw new Error('Required read tool missing');
  await writeFile(new URL('read-tool-contracts.json',import.meta.url),JSON.stringify(tools,null,2),{mode:0o600});
  const tokens = credentials.tokens(entry.config.url);
  console.log(JSON.stringify({state:connection.state,tools:tools.map(t=>t.name),refreshTokenPresent:!!tokens?.refresh_token,tokenFields:Object.keys(tokens??{})}));
} catch (error) {
  // Auth errors can contain callback URLs; report their class, not raw details.
  console.error('Discovery failed:',error?.constructor?.name ?? 'Error');
  process.exitCode=1;
} finally {
  await connection.close();
}

