package superhuman

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"golang.org/x/oauth2"
)

const (
	endpoint      = "https://mcp.mail.superhuman.com/mcp"
	authHost      = "mcp.auth.mail.superhuman.com"
	tokenEndpoint = "https://" + authHost + "/oauth2/token"
)

// This is deliberately not an arbitrary MCP client: neither configuration nor
// a model may change the resource, OAuth authority, or callable operation.
// Use the official SDK for protocol negotiation, discovery, and PKCE instead
// of maintaining our own implementation of those security-sensitive protocols.
type guardedTransport struct{ base http.RoundTripper }

func (t guardedTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	if !allowedURL(req.URL) {
		return nil, errors.New("Superhuman request outside the allowed HTTPS origins")
	}
	resp, err := t.base.RoundTrip(req)
	if err != nil {
		return nil, safeError("Superhuman HTTPS request", err)
	}
	resp.Body = http.MaxBytesReader(nil, resp.Body, 4<<20)
	return resp, nil
}

func allowedURL(u *url.URL) bool {
	return u != nil && u.Scheme == "https" && u.User == nil && u.Fragment == "" &&
		(u.Host == "mcp.mail.superhuman.com" || u.Host == authHost)
}

func newHTTPClient() *http.Client {
	return &http.Client{
		Timeout:   30 * time.Second,
		Transport: guardedTransport{http.DefaultTransport},
		// No redirects: a token, code, or client secret must never be forwarded
		// to a location chosen in an HTTP response, even within the allowlist.
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
	}
}

func safeError(operation string, err error) error {
	for _, known := range []error{context.Canceled, context.DeadlineExceeded, ErrLoginRequired} {
		if errors.Is(err, known) {
			return fmt.Errorf("%s: %w", operation, known)
		}
	}
	// External error strings may echo authorization codes, tokens, or mail.
	// Do not wrap them: even downstream debug logging must not recover them.
	return fmt.Errorf("%s failed; check connectivity or sign in again (remote details suppressed)", operation)
}

// storedAuth never opens a browser or expands scopes. An expired access token
// refreshes via the saved grant; a rejected grant requires explicit login.
type storedAuth struct{ source oauth2.TokenSource }

func (a storedAuth) TokenSource(context.Context) (oauth2.TokenSource, error) { return a.source, nil }
func (a storedAuth) Authorize(_ context.Context, _ *http.Request, resp *http.Response) error {
	resp.Body.Close()
	return ErrLoginRequired
}

func newClient() *mcp.Client {
	return mcp.NewClient(&mcp.Implementation{Name: "mrmr", Version: "dev"}, &mcp.ClientOptions{
		Capabilities:   &mcp.ClientCapabilities{},
		MultiRoundTrip: &mcp.MultiRoundTripOptions{Disabled: true},
		Logger:         slog.New(slog.NewTextHandler(io.Discard, nil)),
	})
}

// Check authenticates without interactive fallback, checks the required tool
// catalog, and counts linked accounts. It never reads messages, changes the
// default account, or exposes account addresses in logs or CLI output.
func Check(ctx context.Context, dir string) (int, error) {
	return check(ctx, dir, newHTTPClient())
}

func check(ctx context.Context, dir string, hc *http.Client) (int, error) {
	store, err := openStore(dir)
	if err != nil {
		return 0, err
	}
	defer store.lock.Close()
	record, err := store.read()
	if err != nil {
		return 0, err
	}
	source := &persistingTokens{ctx: context.WithValue(ctx, oauth2.HTTPClient, hc), store: store, record: *record}
	session, err := newClient().Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint: endpoint, HTTPClient: hc, OAuthHandler: storedAuth{source}, DisableStandaloneSSE: true,
	}, &mcp.ClientSessionOptions{ProtocolVersion: "2025-11-25"})
	if err != nil {
		return 0, safeError("connect to Superhuman", err)
	}
	defer session.Close()
	return checkSession(ctx, session)
}

func checkSession(ctx context.Context, session *mcp.ClientSession) (int, error) {
	wanted := map[string]bool{"list_accounts": false, "list_threads": false, "get_thread": false, "get_message": false}
	params := &mcp.ListToolsParams{}
	// Catalog pagination is bounded too. A server can't keep the CLI alive by
	// returning an endless cursor chain; no tool has been invoked at this point.
	for page := 0; ; page++ {
		if page == 10 {
			return 0, errors.New("Superhuman tool catalog exceeded 10 pages")
		}
		result, err := session.ListTools(ctx, params)
		if err != nil {
			return 0, safeError("list Superhuman tools", err)
		}
		for _, tool := range result.Tools {
			if _, ok := wanted[tool.Name]; ok {
				wanted[tool.Name] = true
			}
		}
		if result.NextCursor == "" {
			break
		}
		if result.NextCursor == params.Cursor {
			return 0, errors.New("Superhuman tool catalog repeated a cursor")
		}
		params.Cursor = result.NextCursor
	}
	for name, present := range wanted {
		if !present {
			return 0, fmt.Errorf("Superhuman is missing required read tool %s", name)
		}
	}
	// Fixed name and fixed arguments are the authority boundary. Server tool
	// annotations are hints, not permission; write tools are never dispatched.
	result, err := session.CallTool(ctx, &mcp.CallToolParams{Name: "list_accounts", Arguments: map[string]any{}})
	if err != nil {
		return 0, safeError("list Superhuman accounts", err)
	}
	if result.IsError {
		return 0, errors.New("Superhuman rejected account listing")
	}
	var accounts struct {
		Accounts []struct {
			Email string `json:"accountEmail"`
		} `json:"accounts"`
	}
	// Prefer the typed payload. Older servers may only return JSON text; never
	// interpret free-form prose or fetch a URL from a tool result to recover it.
	var data []byte
	if result.StructuredContent != nil {
		data, err = json.Marshal(result.StructuredContent)
	} else if len(result.Content) == 1 {
		if text, ok := result.Content[0].(*mcp.TextContent); ok {
			data = []byte(text.Text)
		}
	}
	if err != nil || json.Unmarshal(data, &accounts) != nil || len(accounts.Accounts) == 0 {
		return 0, errors.New("Superhuman returned no usable linked accounts")
	}
	seen := make(map[string]bool)
	for _, account := range accounts.Accounts {
		if account.Email == "" || seen[account.Email] {
			return 0, errors.New("invalid Superhuman linked-account response")
		}
		seen[account.Email] = true
	}
	return len(accounts.Accounts), nil
}

package superhuman

import (
	"context"
	"crypto/subtle"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strconv"
	"time"

	"github.com/modelcontextprotocol/go-sdk/auth"
	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/modelcontextprotocol/go-sdk/oauthex"
	"golang.org/x/oauth2"
)

// Login is the only interactive path. It creates an independent mrmr grant,
// leaves any old credentials intact on failure, and never calls a mail tool.
// showURL is a local human prompt, not a logger: authorization links should not
// be put into persistent service logs or shared with another person.
func Login(ctx context.Context, dir string, port int, showURL func(string) error) error {
	return login(ctx, dir, port, showURL, newHTTPClient())
}

func login(ctx context.Context, dir string, port int, showURL func(string) error, hc *http.Client) error {
	if port < 0 || port > 65535 || showURL == nil {
		return errors.New("invalid login callback configuration")
	}
	ctx, cancel := context.WithTimeout(ctx, 5*time.Minute)
	defer cancel()
	store, err := openStore(dir)
	if err != nil {
		return err
	}
	defer store.lock.Close()
	listener, err := net.Listen("tcp4", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
	if err != nil {
		return errors.New("cannot bind OAuth callback on loopback; choose another callback port")
	}
	defer listener.Close()
	redirect := "http://" + listener.Addr().String() + "/callback"
	saved := false
	handler, err := auth.NewAuthorizationCodeHandler(&auth.AuthorizationCodeHandlerConfig{
		Client: hc, RedirectURL: redirect, RequestRefreshToken: true,
		// Identity scopes are not a server-side read-only mail grant. Our fixed
		// tool calls enforce read-only behavior regardless of the consent scope.
		ScopeFilter: func([]string) []string { return []string{"openid", "email", "profile"} },
		DynamicClientRegistrationConfig: &auth.DynamicClientRegistrationConfig{
			Metadata: &oauthex.ClientRegistrationMetadata{
				ClientName: "mrmr", RedirectURIs: []string{redirect},
				GrantTypes: []string{"authorization_code", "refresh_token"},
				ResponseTypes: []string{"code"}, TokenEndpointAuthMethod: "none",
			},
		},
		AuthorizationCodeFetcher: func(ctx context.Context, args *auth.AuthorizationArgs) (*auth.AuthorizationResult, error) {
			return receiveCode(ctx, listener, args.URL, showURL)
		},
		NewTokenSource: func(ctx context.Context, config *oauth2.Config, token *oauth2.Token) (oauth2.TokenSource, error) {
			record := credentialRecord{Version: 1, Resource: endpoint, Config: *config, Token: *token}
			if err := store.write(&record); err != nil {
				return nil, err
			}
			saved = true
			return &persistingTokens{ctx: ctx, store: store, record: record}, nil
		},
	})
	if err != nil {
		return safeError("prepare Superhuman authorization", err)
	}
	session, err := newClient().Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint: endpoint, HTTPClient: hc, OAuthHandler: handler, DisableStandaloneSSE: true,
	}, &mcp.ClientSessionOptions{ProtocolVersion: "2025-11-25"})
	if err != nil {
		return safeError("Superhuman login", err)
	}
	defer session.Close()
	if !saved {
		return errors.New("Superhuman did not issue a refreshable OAuth grant")
	}
	return nil
}

func receiveCode(ctx context.Context, listener net.Listener, authURL string, showURL func(string) error) (*auth.AuthorizationResult, error) {
	u, err := url.Parse(authURL)
	if err != nil || !allowedURL(u) || u.Host != authHost || u.Query().Get("state") == "" {
		return nil, errors.New("unexpected Superhuman authorization URL")
	}
	results := make(chan *auth.AuthorizationResult, 1)
	mux := http.NewServeMux()
	mux.HandleFunc("GET /callback", callbackHandler(listener.Addr().String(), u.Query().Get("state"), results))
	server := &http.Server{Handler: mux, ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 5 * time.Second, WriteTimeout: 5 * time.Second, MaxHeaderBytes: 8192}
	done := make(chan error, 1)
	go func() { done <- server.Serve(listener) }()
	// The listener, server, and goroutine belong to this attempt. Cancellation,
	// denied consent, and an abandoned browser all close and join the server.
	defer func() { server.Close(); <-done }()
	if err := showURL(authURL); err != nil {
		return nil, errors.New("cannot display the Superhuman sign-in URL")
	}
	select {
	case result := <-results:
		if result.Code == "" {
			return nil, errors.New("Superhuman authorization was denied")
		}
		// The SDK verifies PKCE, state again, and the response issuer before
		// exchanging this code. No raw query or remote error is ever logged.
		return result, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

func callbackHandler(host, state string, results chan<- *auth.AuthorizationResult) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		w.Header().Set("Referrer-Policy", "no-referrer")
		w.Header().Set("Content-Security-Policy", "default-src 'none'")
		q := r.URL.Query()
		// Reject stray local requests without consuming the real callback. The
		// state must match before either an error or a code ends this attempt.
		if r.Host != host || len(q["state"]) != 1 || subtle.ConstantTimeCompare([]byte(q.Get("state")), []byte(state)) != 1 ||
			len(q["code"]) > 1 || len(q["iss"]) > 1 || len(q["error"]) > 1 ||
			(q.Get("code") == "" && q.Get("error") == "") || (q.Get("code") != "" && q.Get("error") != "") {
			http.Error(w, "Invalid authorization callback.", http.StatusBadRequest)
			return
		}
		result := &auth.AuthorizationResult{Code: q.Get("code"), State: q.Get("state"), Iss: q.Get("iss")}
		select {
		case results <- result:
			fmt.Fprintln(w, "Authorization response received. Return to the mrmr terminal to check the result.")
		default:
			http.Error(w, "Authorization response already received.", http.StatusConflict)
		}
	}
}

package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/heath0xff/mrmr/internal/superhuman"
)

func authCommand(args []string) error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	return runAuth(ctx, args, os.Stdout)
}

// Authentication does not load a flow or open its database. This lets a user
// establish and check the connection before giving a source any mail access.
func runAuth(ctx context.Context, args []string, out io.Writer) error {
	if len(args) < 2 || args[1] != "superhuman" || (args[0] != "login" && args[0] != "check") {
		return errors.New("usage: mrmr auth <login|check> superhuman [-state-dir /absolute/private/path] [-callback-port 18742 (login only)]")
	}
	fs := flag.NewFlagSet("auth "+args[0]+" superhuman", flag.ContinueOnError)
	dir := fs.String("state-dir", "", "private credential directory (default: user config directory/mrmr/superhuman)")
	port := 18742
	if args[0] == "login" {
		fs.IntVar(&port, "callback-port", port, "loopback callback port; forward this port when signing in over SSH")
	}
	if err := fs.Parse(args[2:]); err != nil {
		return err
	}
	if fs.NArg() != 0 {
		return errors.New("unexpected auth arguments")
	}
	if *dir == "" {
		var err error
		*dir, err = superhuman.DefaultDir()
		if err != nil {
			return err
		}
	}
	if args[0] == "login" {
		if err := superhuman.Login(ctx, *dir, port, func(url string) error {
			_, err := fmt.Fprintf(out, "Open this private sign-in link in your browser (expires in 5 minutes):\n%s\n", url)
			return err
		}); err != nil {
			return err
		}
		_, err := fmt.Fprintln(out, "Signed in to Superhuman. Credentials saved privately by mrmr; no email read or polling started.")
		return err
	}
	// A check is bounded and non-interactive, including token refresh. It is
	// deliberately not a hidden way to sign in or obtain broader permissions.
	ctx, cancel := context.WithTimeout(ctx, time.Minute)
	defer cancel()
	count, err := superhuman.Check(ctx, *dir)
	if err != nil {
		return err
	}
	_, err = fmt.Fprintf(out, "Superhuman connected: %d linked account(s); required read tools available. No email bodies fetched.\n", count)
	return err
}

